SELECT 'projects' AS section, COUNT(*) AS count_value FROM projects WHERE enterprise_name = '海豚知道';
SELECT 'questions' AS section, COUNT(*) AS count_value FROM questions q JOIN projects p ON q.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'ai_responses' AS section, COUNT(*) AS count_value FROM ai_responses a JOIN questions q ON a.question_id = q.id JOIN projects p ON q.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'analysis_results' AS section, COUNT(*) AS count_value FROM analysis_results ar JOIN ai_responses a ON ar.response_id = a.id JOIN questions q ON a.question_id = q.id JOIN projects p ON q.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'geo_scores' AS section, COUNT(*) AS count_value FROM geo_scores gs JOIN projects p ON gs.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'optimization_tasks' AS section, COUNT(*) AS count_value FROM optimization_tasks ot JOIN projects p ON ot.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'content_templates' AS section, COUNT(*) AS count_value FROM content_templates ct JOIN projects p ON ct.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'reports' AS section, COUNT(*) AS count_value FROM reports r JOIN projects p ON r.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'geo_articles_total' AS section, COUNT(*) AS count_value FROM geo_articles ga JOIN projects p ON ga.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'geo_articles_published' AS section, COUNT(*) AS count_value FROM geo_articles ga JOIN projects p ON ga.project_id = p.id WHERE p.enterprise_name = '海豚知道' AND ga.status = '已发布';
SELECT 'geo_publish_records' AS section, COUNT(*) AS count_value FROM geo_publish_records gpr JOIN geo_articles ga ON gpr.article_id = ga.id JOIN projects p ON ga.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'enterprise_profiles' AS section, COUNT(*) AS count_value FROM enterprise_geo_profiles ep JOIN projects p ON ep.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'asset_sources' AS section, COUNT(*) AS count_value FROM geo_asset_sources s JOIN projects p ON s.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'customer_cases' AS section, COUNT(*) AS count_value FROM customer_cases cc JOIN projects p ON cc.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'competitor_profiles' AS section, COUNT(*) AS count_value FROM competitor_profiles cp JOIN projects p ON cp.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'compliance_rules' AS section, COUNT(*) AS count_value FROM compliance_rules cr JOIN projects p ON cr.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'content_style_profiles' AS section, COUNT(*) AS count_value FROM content_style_profiles csp JOIN projects p ON csp.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'publish_strategies' AS section, COUNT(*) AS count_value FROM publish_strategies ps JOIN projects p ON ps.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT ga.id, ga.title, ga.article_type, ga.status FROM geo_articles ga JOIN projects p ON ga.project_id = p.id WHERE p.enterprise_name = '海豚知道' ORDER BY ga.id LIMIT 10;
SELECT gpr.article_id, gpr.platform, gpr.publish_status, gpr.publish_url, gpr.index_status, gpr.ai_mention_status, gpr.ai_recommend_status FROM geo_publish_records gpr JOIN geo_articles ga ON gpr.article_id = ga.id JOIN projects p ON ga.project_id = p.id WHERE p.enterprise_name = '海豚知道' ORDER BY gpr.id LIMIT 5;
SELECT r.id, r.title, LEFT(r.summary, 180) AS summary_excerpt FROM reports r JOIN projects p ON r.project_id = p.id WHERE p.enterprise_name = '海豚知道' ORDER BY r.id DESC LIMIT 3;

